import { NextResponse } from "next/server";

export async function GET(
  _req: Request,
  { params }: { params: Promise<{ org: string; invoice: string }> },
) {
  const { org, invoice } = await params;
  const body = [
    `THEFT — ${org}`,
    `Invoice: ${invoice}`,
    "",
    "Plan: Team",
    "Period: as billed",
    "Total: $60.00 USD",
    "",
    "This is a placeholder invoice payload. The real PDF is generated by",
    "the billing pipeline; in dev we return a plain-text stub so the link",
    "works end-to-end.",
  ].join("\n");
  return new NextResponse(body, {
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "content-disposition": `attachment; filename="${invoice}.txt"`,
    },
  });
}
